#!/usr/bin/env bash
#
# A wizard - walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library - delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear - wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" - opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later - it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" - clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." - a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." - a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL - open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser - visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser - visit it manually: $url"
}

# pause "msg" - wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" - y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY - current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" - read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" - like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE - upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE - set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name - gh not ready; set it later"
}

# set_var NAME VALUE - set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name - gh not ready; set it later"
}

# finish - clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES - Jira Cloud and Linear credentials for the evidence connectors (CR-3).
#
# Run from the repo root: bash scripts/setup_connectors.sh
#
# Nothing here goes into CI. The offline suite needs no credentials, and the
# eval gate runs on the synthetic corpus, so these three-plus-one variables are
# local-only and land in .env (gitignored).
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=7

banner "AuditReady - Jira & Linear evidence connectors"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Jira - create a free Cloud site"
say "The Jira connector reads issues over the REST API. You need a Cloud site"
say "to read from; the free tier is enough and takes about two minutes."
say ""
say "If you already have a site, skip the signup and just note its host."
open_url "https://www.atlassian.com/software/jira/free"
step "Sign up (or sign in), and let it create a site for you."
step "When it lands, look at the address bar. The host is the part that looks"
step "like  mycompany.atlassian.net  - that is what we need, not the full path."
pause
ask JIRA_SITE "Jira site host (e.g. mycompany.atlassian.net):"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Jira - a project with auditable issues"
say "The audit needs issues that look like service tickets, not empty stubs."
say "Two or three is plenty for a demo."
open_url "https://${JIRA_SITE}/jira/projects"
step "Create a project (any template; 'Service management' is closest)."
step "Note its KEY - the short prefix on issue ids, e.g. AUD in AUD-12."
say ""
say "You can leave the project EMPTY and let the seed script fill it after the"
say "token stage:  uv run python scripts/seed_demo_evidence.py --jira <KEY>"
say "It creates four closed issues with an approval, a CHG-/EML- link, a request"
say "with no approval, and the planted injection string."
say ""
say "Or add 2-3 issues by hand, and make them resemble real evidence:"
step "give one a comment that reads like an approval, e.g."
step "  \"Approved for release by Priya Nair, 2026-03-04.\""
step "mention a linked record in the text of another, e.g."
step "  \"Root cause traced to CHG-3001. Client told in EML-2002.\""
say ""
say "That second one matters: the connector recovers CHG-/EML- ids out of prose"
say "and the agent then joins those records by id. It is the linked-evidence"
say "claim, working on live data instead of the synthetic corpus."
pause
ask JIRA_PROJECT "Jira project key (e.g. AUD):"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Jira - API token"
say "Atlassian deprecated password auth. A script authenticates with your"
say "account email plus an API token, sent as HTTP Basic."
open_url "https://id.atlassian.com/manage/api-tokens"
step "Click 'Create API token', name it 'auditready', and copy the value."
step "You only get to see it once - copy it before closing the dialog."
say ""
say "The email must be the Atlassian account that minted the token, or the"
say "site answers 401."
ask JIRA_EMAIL "Atlassian account email:"
ask_secret JIRA_TOKEN "Paste the API token:"
write_env AUDITREADY_JIRA_SITE "$JIRA_SITE"
write_env AUDITREADY_JIRA_EMAIL "$JIRA_EMAIL"
write_env AUDITREADY_JIRA_TOKEN "$JIRA_TOKEN"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Jira - verify"
say "This hits the real site, maps what comes back, and pushes it through the"
say "same contract gate every source passes. It spends no LLM calls."
say ""
if confirm "Run the Jira smoke test now?"; then
  if uv run python scripts/smoke_jira.py --project "$JIRA_PROJECT" --limit 3; then
    say ""
    printf '  %s✓ Jira connector is live%s\n' "$GREEN" "$RESET"
  else
    say ""
    printf '  %s! Jira smoke test failed - the message above names the cause.%s\n' "$YELLOW" "$RESET"
    say "Common ones: wrong host, the email is not the token's account (401),"
    say "or the project key is wrong / not browsable by that account (404)."
    SKIPPED+=("Jira smoke test failed - re-run: uv run python scripts/smoke_jira.py --project $JIRA_PROJECT")
    pause
  fi
else
  SKIPPED+=("Jira smoke test skipped - run: uv run python scripts/smoke_jira.py --project $JIRA_PROJECT")
fi

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Linear - workspace, team, and issues"
say "The Linear connector reads the same record shape over GraphQL instead of"
say "REST. Free tier is fine."
open_url "https://linear.app/signup"
step "Sign up (or sign in) and let it create a workspace and a first team."
step "Note the team KEY - again the prefix on issue ids, e.g. AUD in AUD-12."
say "  Settings -> Teams -> your team, or just look at any issue id."
say ""
say "Same shortcut as Jira: leave it empty and run"
say "  uv run python scripts/seed_demo_evidence.py --linear <KEY>"
say "after the key stage. Or add 2-3 issues by hand, plus one Linear-specific thing:"
step "set a priority on at least one issue. Linear's default is 'No priority',"
step "which the connector records as an admitted guess rather than reading it"
step "as medium - worth seeing both branches."
step "label one 'Bug' so the type maps to 'incident' instead of defaulting."
pause
ask LINEAR_TEAM "Linear team key (e.g. AUD):"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Linear - personal API key"
say "Linear takes a personal API key, sent raw in the Authorization header"
say "with no 'Bearer' prefix. Getting that wrong returns a 400 that reads"
say "like a bad key, so the connector's error message calls it out."
open_url "https://linear.app/settings/account/security"
step "Find 'Personal API keys' and create one named 'auditready'."
step "Copy it now - it is shown once."
ask_secret LINEAR_TOKEN "Paste the Linear API key:"
write_env AUDITREADY_LINEAR_TOKEN "$LINEAR_TOKEN"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Linear - verify"
say "Same check as Jira: fetch, map, and pass the contract gate. No LLM calls."
say ""
say "This one also proves the GraphQL query still matches Linear's schema -"
say "a renamed field comes back as HTTP 200 with an errors array, which the"
say "connector refuses rather than reporting as an empty audit."
say ""
if confirm "Run the Linear smoke test now?"; then
  if uv run python scripts/smoke_linear.py --team "$LINEAR_TEAM" --limit 3; then
    say ""
    printf '  %s✓ Linear connector is live%s\n' "$GREEN" "$RESET"
  else
    say ""
    printf '  %s! Linear smoke test failed - the message above names the cause.%s\n' "$YELLOW" "$RESET"
    say "If it says the team returned no issues, drop --team to fetch the whole"
    say "workspace and check the key."
    SKIPPED+=("Linear smoke test failed - re-run: uv run python scripts/smoke_linear.py --team $LINEAR_TEAM")
    pause
  fi
else
  SKIPPED+=("Linear smoke test skipped - run: uv run python scripts/smoke_linear.py --team $LINEAR_TEAM")
fi

say ""
say "Next, to audit live evidence instead of the synthetic corpus:"
say ""
say "  uv run python audit/connectors.py --source jira --project $JIRA_PROJECT \\"
say "      --out assistant/data/live-jira --artifacts-from assistant/data/corpus"
say ""
say "  AUDITREADY_CORPUS_DIR=assistant/data/live-jira \\"
say "  AUDITREADY_PERSIST_DIR=.chroma-live \\"
say "      uv run python audit/batch.py --corpus assistant/data/live-jira \\"
say "      --pack assistant/data/checklists/iso9001.yaml"
say ""
say "Expect a low readiness score and gaps citing a missing signoff. Neither"
say "Jira nor Linear carries an approval record, so that is the honest finding."

finish
